    "summarize"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/cesumilo/opencode-compact-instructions"
  },
  "license": "MIT",
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
